package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.fan.FanPersonality;

import org.junit.Test;

import java.util.*;

public class FanChatManagerTest {
    @Test
    public void quoteParsing() {
        assertEquals(
                Arrays.asList("hello, there", "nice cape"),
                FanQuoteLibrary.parse(" hello, there \n\n nice cape "));
        assertEquals(Arrays.asList("hi", "gz"), FanQuoteLibrary.parse(" hi, ,gz, "));
        assertEquals(Arrays.asList("hi", "gz"), FanQuoteLibrary.parse("hi\r\ngz"));
        assertTrue(FanQuoteLibrary.parse(" , , ").isEmpty());
        assertTrue(FanQuoteLibrary.parse(null).isEmpty());
        assertTrue(
                FanQuoteLibrary.pool(
                                FanPersonality.EXCITED,
                                CustomQuoteMode.CUSTOM_ONLY,
                                FanQuoteLibrary.parse(""))
                        .isEmpty());
    }

    @Test
    public void offAndEmptyCustomModeSuppressEventChat() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(8));
        chat.configure(ChatFrequency.OFF, CustomQuoteMode.MIXED, "", 0);
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) fan.overheadText = null;
        chat.react(scene.manager.getFans(), 1, new String[] {"gz"});
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans())
            assertNull(fan.overheadText);
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "", 0);
        for (int i = 0; i < 100; i++) chat.tick(scene.manager.getFans(), i);
        chat.react(scene.manager.getFans(), 100, new String[] {"gz"});
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans())
            assertNull(fan.overheadText);
    }

    @Test
    public void spamKeepsMostOfTheCrowdTalking() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.config.size = 30;
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(18));
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.BUILT_IN_ONLY, "", 0);
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) {
            fan.nextChatTick = 0;
            fan.overheadText = null;
        }
        int busyTicks = 0, messages = 0;
        for (int tick = 1; tick <= 100; tick++) {
            int[] old = new int[30];
            for (int i = 0; i < 30; i++) old[i] = scene.manager.getFans().get(i).overheadExpiryTick;
            chat.tick(scene.manager.getFans(), tick);
            int speaking = 0;
            for (int i = 0; i < 30; i++) {
                com.celebritymode.fan.FanEntity fan = scene.manager.getFans().get(i);
                if (fan.overheadText != null) speaking++;
                if (old[i] != fan.overheadExpiryTick) messages++;
            }
            if (speaking >= 20) busyTicks++;
        }
        assertTrue("Near-constant visible chatter", busyTicks >= 95);
        assertTrue("Many messages each second", messages > 1200);
    }

    @Test
    public void fansRememberRecentLinesAndContextChangesReachTheCrowd() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        com.celebritymode.fan.FanEntity fan = scene.manager.getFans().get(0);
        List<com.celebritymode.fan.FanEntity> fans = Collections.singletonList(fan);
        FanChatManager chat = new FanChatManager(new Random(4));
        chat.clear(fans);
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.BUILT_IN_ONLY, "", 0);
        chat.setContext(
                new FanChatContext(
                        "LocalHero",
                        "",
                        "Goblin",
                        FanChatContext.Activity.COMBAT,
                        null,
                        0,
                        0,
                        false,
                        false));
        Deque<String> recent = new ArrayDeque<>();
        String previous = null;
        int messages = 0, targetLines = 0, repeat = 0;
        for (int tick = 1; tick < 400; tick++) {
            int expiry = fan.overheadExpiryTick;
            chat.tick(fans, tick);
            if (expiry == fan.overheadExpiryTick) continue;
            String line = fan.overheadText.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9 ]", "");
            assertNotEquals(previous, line);
            if (recent.contains(line)) repeat++;
            recent.addLast(line);
            if (recent.size() > 12) recent.removeFirst();
            if (line.contains("goblin")) targetLines++;
            previous = line;
            messages++;
        }
        assertTrue(messages > 200);
        assertTrue(targetLines > 30);
        assertTrue("Per-fan recent duplicates: " + repeat, repeat <= 2);
        chat.setContext(FanChatContext.idle("New Name", ""));
        for (int tick = 400; tick < 440; tick++) {
            int expiry = fan.overheadExpiryTick;
            chat.tick(fans, tick);
            if (expiry != fan.overheadExpiryTick) {
                assertFalse(fan.overheadText.toLowerCase(Locale.ENGLISH).contains("goblin"));
                assertFalse(fan.overheadText.contains("LocalHero"));
            }
        }
    }

    @Test
    public void customLevelEventsUseActualLevelAndRemainVisibleBeforeNextChatter() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(9));
        chat.configure(
                ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "{player} {level} {skill}", 0);
        chat.setContext(FanChatContext.idle("LocalHero", ""));
        chat.level(scene.manager.getFans(), 10, net.runelite.api.Skill.MINING, 82);
        int reactions = 0;
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) {
            if ("LocalHero 82 Mining".equals(fan.overheadText)) {
                assertTrue(fan.nextChatTick >= 13);
                reactions++;
            }
        }
        assertEquals(2, reactions);
    }

    @Test
    public void seededSchedulingBounds() {
        FanChatManager manager = new FanChatManager(new Random(10));
        for (ChatFrequency f : ChatFrequency.values()) {
            manager.configure(f, CustomQuoteMode.MIXED, "", 100);
            if (f == ChatFrequency.OFF) {
                assertEquals(Integer.MAX_VALUE, manager.getNextTick());
                manager.tick(Collections.emptyList(), 10000);
                assertEquals(Integer.MAX_VALUE, manager.getNextTick());
            } else
                for (int tick = 100; tick < 1000; tick += 30) {
                    manager.configure(f, CustomQuoteMode.MIXED, "", tick);
                    int delay = manager.getNextTick() - tick;
                    assertTrue(delay >= f.minimumTicks && delay <= f.maximumTicks);
                }
        }
    }

    @Test
    public void avoidsImmediateDuplicateWheneverPossible() {
        FanChatManager manager = new FanChatManager(new Random(8));
        String previous = null;
        for (int i = 0; i < 100; i++) {
            String q = manager.choose(Arrays.asList("gz", "gz", "hi"));
            assertNotEquals(previous, q);
            previous = q;
        }
        assertNull(manager.choose(Collections.emptyList()));
        assertEquals("only", manager.choose(Collections.singletonList("only")));
    }
}

package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.TestScene;

import net.runelite.api.*;

import org.junit.Test;

public class FanActivityTrackerTest {
    @Test
    public void loginXpIsNotAnActivityButRealGainsAreAndExpire() {
        TestScene scene = new TestScene();
        scene.skillXp.put(Skill.WOODCUTTING, 40000);
        FanActivityTracker tracker = new FanActivityTracker();
        tracker.experience(Skill.WOODCUTTING, 40000, 1);
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
        tracker.experience(Skill.WOODCUTTING, 40075, 2);
        FanChatContext context = observe(tracker, scene, 3);
        assertEquals(FanChatContext.Activity.SKILLING, context.activity);
        assertEquals(Skill.WOODCUTTING, context.skill);
        assertEquals(75, context.gainedXp);
        assertEquals(70, context.level);
        assertEquals(
                FanChatContext.Activity.RUNNING,
                tracker.observe(scene.client, scene.player, "", true, true, 4).activity);
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 13).activity);
        assertNull(observe(tracker, scene, 13).skill);
        tracker.clear();
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
    }

    @Test
    public void bankMovementGearAndNoncombatMagicUseObservedState() {
        TestScene scene = new TestScene();
        FanActivityTracker tracker = new FanActivityTracker();
        tracker.observe(scene.client, scene.player, "bow", true, true, 1);
        assertEquals(
                FanChatContext.Activity.WALKING,
                tracker.observe(scene.client, scene.player, "bow", true, false, 2).activity);
        FanChatContext changed =
                tracker.observe(scene.client, scene.player, "staff", true, true, 3);
        assertEquals(FanChatContext.Activity.RUNNING, changed.activity);
        assertTrue(changed.gearChanged);
        assertFalse(
                tracker.observe(scene.client, scene.player, "staff", false, false, 12).gearChanged);
        tracker.experience(Skill.MAGIC, 65, 12);
        assertEquals(FanChatContext.Activity.SKILLING, observe(tracker, scene, 13).activity);
        scene.bankOpen = true;
        assertEquals(FanChatContext.Activity.BANKING, observe(tracker, scene, 13).activity);
    }

    @Test
    public void TalkingToNpcIsNotFightingAndLowHealthNeedsCombat() {
        TestScene scene = new TestScene();
        scene.interacting =
                TestScene.proxy(
                        NPC.class,
                        (method, args) -> {
                            if (method.equals("getName")) return "<col=ffff00>Goblin</col>";
                            if (method.equals("getCombatLevel")) return 2;
                            if (method.equals("getHealthRatio")) return -1;
                            return null;
                        });
        scene.hp = 10;
        FanActivityTracker tracker = new FanActivityTracker();
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
        assertFalse(observe(tracker, scene, 1).lowHealth);
        tracker.menu("Attack", 2);
        FanChatContext fighting = observe(tracker, scene, 2);
        assertEquals(FanChatContext.Activity.COMBAT, fighting.activity);
        assertEquals("Goblin", fighting.target);
        assertTrue(fighting.lowHealth);
        scene.interacting = null;
        assertFalse(observe(tracker, scene, 3).lowHealth);
        assertEquals("", observe(tracker, scene, 3).target);
    }

    private static FanChatContext observe(FanActivityTracker tracker, TestScene scene, int tick) {
        return tracker.observe(scene.client, scene.player, "", false, false, tick);
    }
}

package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.fan.FanPersonality;

import org.junit.Test;

import java.util.*;

public class FanDialogueGeneratorTest {
    @Test
    public void composableDialogueHasBroadVarietyAndUsesCurrentName() {
        Random random = new Random(5);
        Set<String> lines = new HashSet<>();
        int personalized = 0;
        for (int i = 0; i < 2000; i++) {
            String quote =
                    FanDialogueGenerator.generate(
                            random,
                            FanPersonality.values()[i % 6],
                            "Current Hero",
                            "Tumeken's shadow");
            if (quote.toLowerCase(Locale.ENGLISH).contains("current hero")) personalized++;
            assertFalse(quote.toLowerCase(Locale.ENGLISH).contains("zezima"));
            assertTrue(quote.length() <= 100);
            lines.add(quote);
        }
        assertTrue("Composed dialogue variety: " + lines.size(), lines.size() > 400);
        assertTrue(
                "Names mixed with natural observations",
                personalized > 1000 && personalized < 1950);
    }

    @Test
    public void broadCorpusSelectsRelevantObservationsWithoutUnresolvedTokens() {
        Random random = new Random(84);
        Set<String> lines = new HashSet<>();
        int mining = 0, targets = 0, warning = 0;
        for (int i = 0; i < 18000; i++) {
            net.runelite.api.Skill skill =
                    new net.runelite.api.Skill[] {
                                net.runelite.api.Skill.MINING, net.runelite.api.Skill.FISHING,
                                net.runelite.api.Skill.WOODCUTTING, net.runelite.api.Skill.AGILITY,
                                net.runelite.api.Skill.HERBLORE, net.runelite.api.Skill.CRAFTING
                            }
                            [i % 6];
            FanChatContext.Activity activity = FanChatContext.Activity.values()[i / 6 % 6];
            FanChatContext context =
                    new FanChatContext(
                            "Current Hero",
                            "Tumeken's shadow",
                            activity == FanChatContext.Activity.COMBAT ? "Goblin" : "",
                            activity,
                            activity == FanChatContext.Activity.SKILLING ? skill : null,
                            80,
                            100,
                            activity == FanChatContext.Activity.COMBAT,
                            i % 7 == 0);
            String line =
                    FanDialogueGenerator.generate(random, FanPersonality.values()[i % 6], context);
            assertFalse(line, line.contains("{") || line.contains("}"));
            assertTrue(line.length() <= 100);
            if (line.toLowerCase(Locale.ENGLISH).contains("goblin")) targets++;
            if (line.toLowerCase(Locale.ENGLISH).contains("hp") || line.contains("food check"))
                warning++;
            if (line.toLowerCase(Locale.ENGLISH).contains("mining")) mining++;
            if (activity != FanChatContext.Activity.COMBAT)
                assertFalse(line, line.toLowerCase(Locale.ENGLISH).contains("goblin"));
            lines.add(line);
        }
        assertTrue("Distinct composed lines: " + lines.size(), lines.size() > 2500);
        assertTrue("Combat target observations", targets > 500);
        assertTrue("Situational health warnings", warning > 100);
        assertTrue("Actual skill observations", mining > 60);
    }

    @Test
    public void levelReactionsNameTheActualSkillAndLevel() {
        FanChatContext context =
                new FanChatContext(
                        "LocalHero",
                        "",
                        "",
                        FanChatContext.Activity.SKILLING,
                        net.runelite.api.Skill.MINING,
                        82,
                        0,
                        false,
                        false);
        Random random = new Random(4);
        Set<String> lines = new HashSet<>();
        for (int i = 0; i < 100; i++) {
            String quote = FanDialogueGenerator.level(context, random);
            assertTrue(quote.contains("LocalHero"));
            assertTrue(quote.contains("mining") || quote.contains("82"));
            assertFalse(quote.contains("{"));
            lines.add(quote);
        }
        assertTrue(lines.size() >= 8);
    }

    @Test
    public void customQuotesAndEventsUseLiveContextWithoutChangingTheirSource() {
        FanChatManager chat = new FanChatManager(new Random(1));
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "{player} nice {gear}", 0);
        chat.setContext("<col=ff0000>Old Name</col>", "bow");
        assertEquals(
                "Old Name nice bow", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
        chat.setContext("New Name", "staff");
        assertEquals(
                "New Name nice staff", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
        chat.setContext(null, null);
        assertEquals("you nice fit", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
    }
}

package com.celebritymode;

import com.celebritymode.appearance.*;

import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.externalplugins.ExternalPluginManager;

import org.slf4j.LoggerFactory;

import java.util.Random;

/** Developer launcher, as used by the official Plugin Hub template. */
public class CelebrityModePluginTest {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(CelebrityModePlugin.class);
        RuneLite.main(args);
        if (Boolean.getBoolean("celebritymode.verifyModels")) verifyCacheModels();
    }

    /**
     * Opt-in developer check against the actual injected client/cache, even at the login screen.
     */
    private static void verifyCacheModels() {
        Client client = RuneLite.getInjector().getInstance(Client.class);
        ClientThread thread = RuneLite.getInjector().getInstance(ClientThread.class);
        FanModelFactory models = new FanModelFactory(client);
        FanAppearanceFactory appearances = new FanAppearanceFactory(new Random(17), models);
        int[] animationIds = {
            AnimationID.HUMAN_READY,
            AnimationID.HUMAN_WALK_F,
            AnimationID.HUMAN_RUNNING,
            AnimationID.EMOTE_WAVE,
            AnimationID.EMOTE_CHEER,
            AnimationID.SLAYER_ABYSSAL_WHIP_WALK,
            AnimationID.SLAYER_ABYSSAL_WHIP_RUN,
            AnimationID.HUMAN_STAFFREADY
        };
        int[] next = {0};
        int[] attempts = {0};
        FanAppearance[] pending = {null};
        thread.invokeLater(
                () -> {
                    if (client.getGameState() != net.runelite.api.GameState.LOGIN_SCREEN
                            && client.getGameState() != net.runelite.api.GameState.LOGGED_IN)
                        return false;
                    if (++attempts[0] > 1000) {
                        LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                .error("Cache model verification timed out");
                        return true;
                    }
                    try {
                        appearances.advanceCatalog();
                        if (!appearances.getCatalog().complete()) return false;
                        FanGearTier tier = FanGearTier.values()[next[0]];
                        if (pending[0] == null)
                            pending[0] = appearances.createAppearance(next[0], tier);
                        FanAppearance appearance = pending[0];
                        if (tier != FanGearTier.DEFAULT_BOB && appearance.equipment.length == 0)
                            throw new IllegalStateException(
                                    "Empty equipment catalogue for " + tier);
                        Model model = models.createModel(appearance);
                        if (model == null || model.getVerticesCount() == 0) return false;
                        for (int id : animationIds) {
                            Model posed = new AnimationController(client, id).animate(model);
                            if (posed == null || posed.getVerticesCount() == 0) return false;
                        }
                        LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                .info(
                                        "Cache model verification passed: {} ({} vertices, {}"
                                            + " animation sequences; {} wardrobe items; equipment"
                                            + " {})",
                                        tier,
                                        model.getVerticesCount(),
                                        animationIds.length,
                                        appearances.getCatalog().size(),
                                        java.util.Arrays.toString(appearance.equipment));
                        pending[0] = null;
                        return ++next[0] == FanGearTier.values().length;
                    } catch (RuntimeException ex) {
                        if (attempts[0] % 30 == 0)
                            LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                    .debug("Waiting for cache model verification resources", ex);
                        return false;
                    }
                });
    }
}

package com.celebritymode;

import com.celebritymode.appearance.*;
import com.celebritymode.fan.*;
import com.celebritymode.movement.*;

import net.runelite.api.*;
import net.runelite.api.coords.*;

import java.lang.reflect.*;
import java.util.*;

/** In-memory API fixture; uses real RuneLiteObject and AnimationController implementations. */
public final class TestScene {
    public int baseX = 3200, baseY = 3200, plane, viewId = -1, cycle, modelBuilds;
    public final List<Integer> loadedAnimations = new ArrayList<>();
    public boolean bodyCacheReady = true, unsupportedEquipment;
    public int textureCloneCalls;
    public short[] faceTextures;
    public String playerName = "LocalHero";
    public Actor interacting;
    public int playerAnimation = -1, hp = 99;
    public boolean bankOpen;
    public final Map<Skill, Integer> skillXp = new EnumMap<>(Skill.class);
    public boolean instance;
    public int[][][] instanceChunks = new int[4][13][13];
    public final Map<Integer, byte[]> itemDefinitions = new LinkedHashMap<>();
    public WorldPoint playerPosition = new WorldPoint(3232, 3232, 0);
    public GameState state = GameState.LOGGED_IN;
    public final int[][] flags = new int[104][104];
    private final byte[][][] settings = new byte[4][104][104];
    private final int[][][] heights = new int[4][105][105];
    public final Set<RuneLiteObjectController> active =
            Collections.newSetFromMap(new IdentityHashMap<>());
    public final WorldView view;
    public final Player player;
    public final Client client;
    public final CollisionService collision = new CollisionService();
    public final FanAnimations animations;
    public final FanMovementController movement;
    public final FanManager manager;
    public final MutableConfig config = new MutableConfig();

    public TestScene() {
        CollisionData map =
                proxy(CollisionData.class, (m, a) -> m.equals("getFlags") ? flags : null);
        view =
                proxy(
                        WorldView.class,
                        (m, a) -> {
                            switch (m) {
                                case "isInstance":
                                    return instance;
                                case "getInstanceTemplateChunks":
                                    return instanceChunks;
                                case "getId":
                                    return viewId;
                                case "getBaseX":
                                    return baseX;
                                case "getBaseY":
                                    return baseY;
                                case "getPlane":
                                    return plane;
                                case "getSizeX":
                                case "getSizeY":
                                    return 104;
                                case "getCollisionMaps":
                                    return new CollisionData[] {map, map, map, map};
                                case "getTileSettings":
                                    return settings;
                                case "getTileHeights":
                                    return heights;
                                default:
                                    return null;
                            }
                        });
        player =
                proxy(
                        Player.class,
                        (m, a) -> {
                            if (m.equals("getLocalLocation"))
                                return LocalPoint.fromWorld(view, playerPosition);
                            if (m.equals("getName")) return playerName;
                            if (m.equals("getInteracting")) return interacting;
                            if (m.equals("getAnimation")) return playerAnimation;
                            return null;
                        });
        Model model = proxy(Model.class, (m, a) -> null);
        ModelData[] mesh = new ModelData[1];
        mesh[0] =
                proxy(
                        ModelData.class,
                        (m, a) -> {
                            if (m.equals("light")) {
                                modelBuilds++;
                                return model;
                            }
                            if (m.equals("cloneTextures")) {
                                textureCloneCalls++;
                                if (faceTextures == null)
                                    throw new NullPointerException(
                                            "No texture array on untextured mesh");
                                faceTextures = faceTextures.clone();
                                return mesh[0];
                            }
                            if (m.equals("getFaceTextures")) return faceTextures;
                            if (m.equals("getVerticesY")) return new float[3];
                            if (m.equals("getFaceColors"))
                                return new short[] {6798, 8741, 25238, 4626, 4550};
                            return mesh[0];
                        });
        IndexDataBase index =
                proxy(
                        IndexDataBase.class,
                        (m, a) -> {
                            if (m.equals("getFileIds"))
                                return (int) a[0] == 3
                                        ? new int[] {0, 1, 2, 3, 4, 5, 6}
                                        : itemDefinitions.keySet().stream()
                                                .mapToInt(Integer::intValue)
                                                .toArray();
                            if (m.equals("loadData")) {
                                int archive = (int) a[0], id = (int) a[1];
                                if (archive == 3)
                                    return bodyCacheReady
                                            ? new byte[] {
                                                1, (byte) id, 2, 1, 3, (byte) (100 + id), 0
                                            }
                                            : null;
                                if (unsupportedEquipment) return new byte[] {(byte) 199, 0};
                                if (itemDefinitions.containsKey(id)) return itemDefinitions.get(id);
                                return new byte[] {13, 3, 23, 3, (byte) 100, 0, 0};
                            }
                            return null;
                        });
        Animation animation =
                proxy(
                        Animation.class,
                        (m, a) -> {
                            if (m.equals("getFrameLengths")) return new int[] {100, 100};
                            if (m.equals("getDuration")) return 2;
                            if (m.equals("getFrameStep")) return 2;
                            return null;
                        });
        Client[] handle = new Client[1];
        handle[0] =
                proxy(
                        Client.class,
                        (m, a) -> {
                            switch (m) {
                                case "getSkillExperience":
                                    return skillXp.getOrDefault((Skill) a[0], 0);
                                case "getRealSkillLevel":
                                    return a[0] == Skill.HITPOINTS ? 99 : 70;
                                case "getBoostedSkillLevel":
                                    return a[0] == Skill.HITPOINTS ? hp : 70;
                                case "getWidget":
                                    return bankOpen
                                            ? proxy(
                                                    net.runelite.api.widgets.Widget.class,
                                                    (method, args) ->
                                                            method.equals("isHidden")
                                                                    ? false
                                                                    : null)
                                            : null;
                                case "getGameState":
                                    return state;
                                case "getGameCycle":
                                    return cycle;
                                case "getWorldView":
                                case "getTopLevelWorldView":
                                    return view;
                                case "getLocalPlayer":
                                    return player;
                                case "getIndexConfig":
                                    return index;
                                case "mergeModels":
                                case "loadModelData":
                                    return mesh[0];
                                case "loadAnimation":
                                    loadedAnimations.add((int) a[0]);
                                    return animation;
                                case "createRuneLiteObject":
                                    return new RuneLiteObject(handle[0]);
                                case "registerRuneLiteObject":
                                    active.add((RuneLiteObjectController) a[0]);
                                    return null;
                                case "removeRuneLiteObject":
                                    active.remove(a[0]);
                                    return null;
                                case "isRuneLiteObjectRegistered":
                                    return active.contains(a[0]);
                                default:
                                    return null;
                            }
                        });
        client = handle[0];
        collision.bind(view);
        animations = new FanAnimations(client);
        movement = new FanMovementController(collision, animations);
        Random random = new Random(17);
        FanModelFactory models = new FanModelFactory(client);
        FanAppearanceFactory appearances = new FanAppearanceFactory(random, models);
        manager =
                new FanManager(
                        client,
                        config,
                        random,
                        appearances,
                        models,
                        collision,
                        new FormationPlanner(config, collision),
                        movement,
                        animations);
    }

    public void tick() {
        cycle += 30;
        for (RuneLiteObjectController object : new ArrayList<>(active)) object.tick(30);
        manager.onGameTick(player);
    }

    public void populate() {
        for (int i = 0; i < 90; i++) tick();
    }

    public static final class MutableConfig implements CelebrityModeConfig {
        public int size = 8;
        public FormationStyle formation = FormationStyle.ENTOURAGE;
        public boolean space = true;
        public FanGearTier gear = FanGearTier.DEFAULT_BOB;

        @Override
        public int crowdSize() {
            return size;
        }

        @Override
        public FormationStyle formationStyle() {
            return formation;
        }

        @Override
        public boolean respectPersonalSpace() {
            return space;
        }

        @Override
        public FanGearTier crowdGearTier() {
            return gear;
        }
    }

    @FunctionalInterface
    public interface Answer {
        Object answer(String method, Object[] args);
    }

    @SuppressWarnings("unchecked")
    public static <T> T proxy(Class<T> type, Answer answer) {
        return (T)
                Proxy.newProxyInstance(
                        type.getClassLoader(),
                        new Class<?>[] {type},
                        (p, m, a) -> {
                            if (m.getName().equals("equals")) return p == a[0];
                            if (m.getName().equals("hashCode")) return System.identityHashCode(p);
                            if (m.getName().equals("toString"))
                                return "Fixture " + type.getSimpleName();
                            Object result = answer.answer(m.getName(), a);
                            if (result != null) return result;
                            Class<?> r = m.getReturnType();
                            if (r == boolean.class) return false;
                            if (r == int.class) return 0;
                            if (r == long.class) return 0L;
                            if (r == float.class) return 0F;
                            if (r == double.class) return 0D;
                            if (r == byte.class) return (byte) 0;
                            if (r == short.class) return (short) 0;
                            if (r == char.class) return (char) 0;
                            return null;
                        });
    }
}

