    @Test
    public void sustainedThirtyFanScene() {
        TestScene scene = new TestScene();
        scene.config.size = 30;
        scene.populate();
        for (int x = 35; x < 45; x++) scene.flags[x][43] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        for (int round = 0; round < 4; round++) {
            int[][] corners = {{3242, 3232}, {3242, 3242}, {3232, 3242}, {3232, 3232}};
            for (int[] corner : corners)
                while (scene.playerPosition.getX() != corner[0]
                        || scene.playerPosition.getY() != corner[1]) {
                    int speed = round % 2 + 1;
                    int dx = Integer.signum(corner[0] - scene.playerPosition.getX()),
                            dy = Integer.signum(corner[1] - scene.playerPosition.getY());
                    int steps =
                            Math.min(
                                    speed,
                                    Math.max(
                                            Math.abs(corner[0] - scene.playerPosition.getX()),
                                            Math.abs(corner[1] - scene.playerPosition.getY())));
                    scene.playerPosition =
                            FormationPlanner.offset(scene.playerPosition, dx * steps, dy * steps);
                    scene.tick();
                    int cycle = scene.cycle;
                    for (int frame = 1; frame < 30; frame++) {
                        scene.cycle = cycle + frame;
                        scene.manager.onClientTick();
                    }
                    scene.cycle = cycle;
                    assertEquals(30, scene.active.size());
                    assertTrue(scene.manager.getBreadcrumbs().size() <= 80);
                    for (FanEntity fan : scene.manager.getFans())
                        assertTrue(scene.collision.canOccupy(fan.position));
                }
        }
        for (int i = 0; i < 100; i++) scene.tick();
        assertEquals(30, scene.modelBuilds);
        for (FanEntity fan : scene.manager.getFans())
            assertTrue(fan.position.distanceTo(scene.playerPosition) <= 3);
        scene.manager.cleanup();
        assertTrue(scene.active.isEmpty());
    }

    @Test
    public void wordOfMouthArrivalsApproachFromOutsideAndRestartOnEnable() {
        TestScene scene = new TestScene();
        scene.config.size = 30;
        scene.tick(); // The cascade begins at tick 1.
        assertTrue(scene.active.isEmpty());
        int early = 0;
        for (int elapsed = 1; elapsed <= 85; elapsed++) {
            scene.tick();
            int due = 0;
            for (int ordinal = 0; ordinal < 30; ordinal++)
                if (CrowdArrival.dueTick(0, ordinal) <= elapsed) due++;
            assertEquals("Visible arrivals after " + elapsed + " ticks", due, scene.active.size());
            if (elapsed == 4) {
                assertEquals(1, due);
                assertTrue(
                        scene.manager.getFans().get(0).position.distanceTo(scene.playerPosition)
                                >= 4);
            }
            if (elapsed == 15) assertEquals(1, due);
            if (elapsed == 30) {
                early = due;
                assertEquals(3, due);
            }
            if (elapsed == 60) assertTrue(due >= 7 && due < 20);
        }
        assertEquals(30, scene.active.size());
        assertTrue(30 - early > early);
        scene.manager.cleanup();
        scene.tick();
        assertTrue(scene.active.isEmpty());
        scene.populate();
        assertEquals(30, scene.active.size());
    }

    @Test
    public void regionReloadPreservesThePendingWordOfMouthCascade() {
        TestScene scene = new TestScene();
        scene.config.size = 30;
        for (int i = 0; i < 10; i++) scene.tick();
        assertEquals(1, scene.active.size());
        RuneLiteObject spotter = scene.manager.getFans().get(0).object;
        int[] deadlines =
                scene.manager.getFans().stream().mapToInt(fan -> fan.arrivalTick).toArray();
        scene.state = GameState.LOADING;
        scene.manager.onGameStateChanged(scene.state);
        scene.baseX += 8;
        scene.playerPosition = new WorldPoint(3234, 3232, 0);
        scene.state = GameState.LOGGED_IN;
        scene.tick();
        assertSame(spotter, scene.manager.getFans().get(0).object);
        assertEquals(1, scene.active.size());
        for (int i = 0; i < 30; i++)
            assertEquals(deadlines[i], scene.manager.getFans().get(i).arrivalTick);
        scene.populate();
        assertEquals(30, scene.active.size());
    }

    @Test
    public void idleCrowdsGatherAndWanderInEveryModeWithRareEmotes() {
        for (FormationStyle style : FormationStyle.values()) {
            TestScene scene = new TestScene();
            scene.config.size = 30;
            scene.config.formation = style;
            scene.populate();
            int steps = 0, reactions = 0;
            boolean front = false, back = false;
            Map<Integer, FanState> prior = new HashMap<>();
            for (int tick = 0; tick < 400; tick++) {
                Map<Integer, WorldPoint> before = new HashMap<>();
                for (FanEntity fan : scene.manager.getFans()) before.put(fan.id, fan.position);
                scene.tick();
                for (FanEntity fan : scene.manager.getFans()) {
                    if (!fan.position.equals(before.get(fan.id))) steps++;
                    if (fan.state == FanState.REACTION && prior.get(fan.id) != FanState.REACTION)
                        reactions++;
                    prior.put(fan.id, fan.state);
                    assertTrue(fan.position.distanceTo(scene.playerPosition) <= 3);
                    // Passing through another player tile is normal OSRS movement; resting targets
                    // avoid it.
                    assertNotEquals(scene.playerPosition, fan.target);
                    if (fan.position.getY() > scene.playerPosition.getY()) front = true;
                    if (fan.position.getY() < scene.playerPosition.getY()) back = true;
                }
            }
            assertTrue("Frequent wandering in " + style, steps > 1000);
            assertTrue(front && back);
            assertTrue("Rare crowd-wide emotes", reactions <= 4);
        }
    }

    @Test
    public void movingCrowdDoesNotStartEmotesAndStationaryReactionHoldsItsTile() {
        TestScene scene = new TestScene();
        scene.config.size = 8;
        scene.populate();
        for (int i = 0; i < 500; i++) {
            int offset = i % 20;
            scene.playerPosition =
                    new WorldPoint(3232 + (offset < 10 ? offset : 20 - offset), 3232, 0);
            scene.tick();
            for (FanEntity fan : scene.manager.getFans())
                assertNotEquals(FanState.REACTION, fan.state);
        }
        FanEntity fan = scene.manager.getFans().get(0);
        scene.animations.setState(fan, FanState.IDLE);
        fan.movementPath = null;
        scene.animations.react(fan, false);
        WorldPoint position = fan.position;
        for (int i = 0; i < 3; i++) {
            scene.tick();
            assertEquals(position, fan.position);
            assertEquals(FanState.REACTION, fan.state);
        }
        scene.manager.cleanup();
    }

    @Test
    public void runningTurnsInterpolateThroughIntermediateTile() {
        TestScene scene = new TestScene();
        scene.config.size = 1;
        scene.populate();
        FanEntity fan = scene.manager.getFans().get(0);
        LocalPoint start = fan.renderLocation;
        fan.movementPath =
                new LocalPoint[] {
                    start,
                    new LocalPoint(start.getX() + 128, start.getY(), scene.view),
                    new LocalPoint(start.getX() + 128, start.getY() + 128, scene.view)
                };
        fan.movementStartCycle = scene.cycle;
        scene.movement.render(fan, scene.view, scene.cycle + 15);
        assertEquals(start.getX() + 128, fan.renderLocation.getX());
        assertEquals(start.getY(), fan.renderLocation.getY());
        scene.movement.render(fan, scene.view, scene.cycle + 23);
        assertEquals(start.getX() + 128, fan.renderLocation.getX());
        assertTrue(fan.renderLocation.getY() > start.getY());
    }

    @Test
    public void walkRunAndInterpolation() {
        TestScene scene = new TestScene();
        scene.config.size = 1;
        scene.populate();
        FanEntity fan = scene.manager.getFans().get(0);
        // Complete the previous independently scheduled wander before testing a fresh segment.
        scene.movement.render(fan, scene.view, scene.cycle + 30);
        WorldPoint start = fan.position;
        MovementTrail trail = new MovementTrail();
        trail.update(start);
        scene.movement.plan(
                fan, FormationPlanner.offset(start, 1, 0), trail, false, scene.view, scene.cycle);
        assertEquals(FanState.WALKING, fan.state);
        int x = fan.renderLocation.getX();
        scene.movement.render(fan, scene.view, scene.cycle + 15);
        assertEquals(x + 64, fan.renderLocation.getX());
        scene.movement.render(fan, scene.view, scene.cycle + 30);
        assertEquals(x + 128, fan.renderLocation.getX());
        start = fan.position;
        scene.movement.plan(
                fan,
                FormationPlanner.offset(start, 2, 0),
                trail,
                true,
                scene.view,
                scene.cycle + 30);
        assertEquals(FanState.RUNNING, fan.state);
        assertEquals(3, fan.movementPath.length);
        scene.movement.render(fan, scene.view, scene.cycle + 60);
        assertEquals(x + 384, fan.renderLocation.getX());
    }
}

package com.celebritymode.fan;

import static org.junit.Assert.*;

import org.junit.Test;

import java.util.*;

public class CrowdArrivalTest {
    @Test
    public void spotterFriendsAndBranchingWavesMatchOsrsTiming() {
        assertEquals(104, CrowdArrival.dueTick(100, 0));
        int[][] waves = {{1, 2, 18, 29}, {3, 6, 34, 49}, {7, 14, 50, 66}, {15, 29, 66, 83}};
        int latest = 0;
        for (int[] wave : waves) {
            for (int ordinal = wave[0]; ordinal <= wave[1]; ordinal++) {
                int delay = CrowdArrival.dueTick(100, ordinal) - 100;
                assertTrue(
                        "Fan " + ordinal + " delay " + delay, delay >= wave[2] && delay <= wave[3]);
                latest = Math.max(latest, delay);
            }
        }
        assertTrue("Full crowd at 45–50 seconds", latest >= 75 && latest <= 85);
    }

    @Test
    public void jitterIsBoundedDeterministicAndDoesNotConsumeRandomState() {
        Set<Integer> jitters = new HashSet<>();
        Set<Integer> lateTicks = new HashSet<>();
        for (int ordinal = 1; ordinal < CrowdArrival.MAX_FANS; ordinal++) {
            int generation = 31 - Integer.numberOfLeadingZeros(ordinal + 1);
            int genStart = (1 << generation) - 1;
            int base =
                    4
                            + 16 * generation
                            + (int)
                                    Math.round(
                                            (double) (ordinal - genStart) / (1 << generation) * 14);
            int due = CrowdArrival.dueTick(0, ordinal);
            int jitter = due - base;
            assertTrue(jitter >= -2 && jitter <= 2);
            assertEquals(due, CrowdArrival.dueTick(0, ordinal));
            assertEquals(due + 5000, CrowdArrival.dueTick(5000, ordinal));
            assertTrue(due > CrowdArrival.dueTick(0, 0));
            jitters.add(jitter);
            if (ordinal >= 15) lateTicks.add(due);
        }
        assertTrue("Varied reaction delays", jitters.size() >= 4);
        assertTrue("Compounding final wave includes shared ticks", lateTicks.size() < 15);
    }

    @Test
    public void rejectsOrdinalsOutsideTheCrowdLimit() {
        for (int ordinal : new int[] {-1, 30, Integer.MAX_VALUE}) {
            try {
                CrowdArrival.dueTick(0, ordinal);
                fail("Accepted invalid ordinal " + ordinal);
            } catch (IllegalArgumentException expected) {
                assertTrue(expected.getMessage().contains("0 and 29"));
            }
        }
    }
}

package com.celebritymode.overlay;

import com.celebritymode.CelebrityModeConfig;
import com.celebritymode.fan.*;

import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;

import javax.inject.*;

@Singleton
public final class CelebrityModeOverlay extends Overlay {
    private final Client client;
    private final CelebrityModeConfig config;
    private final FanManager manager;

    @Inject
    public CelebrityModeOverlay(Client client, CelebrityModeConfig config, FanManager manager) {
        this.client = client;
        this.config = config;
        this.manager = manager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        WorldView view = manager.getView();
        if (view == null || client.getGameState() != GameState.LOGGED_IN) return null;
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setFont(FontManager.getRunescapeBoldFont());
            FontMetrics metrics = g.getFontMetrics();
            List<Rectangle> placed = new ArrayList<>(30);
            Rectangle viewport =
                    new Rectangle(
                            client.getViewportXOffset(),
                            client.getViewportYOffset(),
                            client.getViewportWidth(),
                            client.getViewportHeight());
            g.clip(viewport);
            if (config.debugMode())
                for (WorldPoint point : manager.getBreadcrumbs())
                    tile(g, view, point, new Color(0, 200, 255, 90));
            for (FanEntity fan : manager.getFans()) {
                LocalPoint location = fan.getRenderLocation();
                if (!fan.isVisible() || location.getWorldView() != view.getId()) continue;
                net.runelite.api.Point p =
                        Perspective.localToCanvas(client, location, view.getPlane(), 210);
                if (p == null || !viewport.contains(p.getX(), p.getY())) continue;
                if (config.debugMode()) {
                    tile(g, view, fan.target, new Color(255, 100, 0, 120));
                    draw(
                            g,
                            metrics,
                            p.getX(),
                            p.getY() + 25,
                            fan.id
                                    + " / "
                                    + fan.formationSlot
                                    + " "
                                    + fan.state
                                    + (fan.target == null
                                            ? ""
                                            : " d=" + fan.position.distanceTo(fan.target)),
                            Color.CYAN);
                }
                int baseline = p.getY();
                if (fan.overheadText != null) {
                    String text = fan.overheadText;
                    Rectangle box =
                            new Rectangle(
                                    p.getX() - metrics.stringWidth(text) / 2,
                                    baseline - metrics.getAscent(),
                                    metrics.stringWidth(text),
                                    metrics.getHeight());
                    // At most one pass per previously placed label, with a restart when pushed
                    // upward.
                    for (int attempts = 0; attempts < placed.size() + 1; attempts++) {
                        boolean moved = false;
                        for (Rectangle other : placed)
                            if (box.intersects(other)) {
                                box.y = other.y - box.height - 2;
                                moved = true;
                                break;
                            }
                        if (!moved) break;
                    }
                    baseline = box.y + metrics.getAscent();
                    if (viewport.intersects(box)) {
                        draw(g, metrics, p.getX(), baseline, text, Color.YELLOW);
                        placed.add(box);
                    }
                }
                if (config.showFanNames())
                    draw(
                            g,
                            metrics,
                            p.getX(),
                            baseline - metrics.getHeight() - 2,
                            fan.displayName,
                            new Color(230, 230, 230));
            }
        } finally {
            g.dispose();
        }
        return null;
    }

    private void tile(Graphics2D g, WorldView view, WorldPoint point, Color color) {
        if (point == null) return;
        LocalPoint local = LocalPoint.fromWorld(view, point);
        if (local == null) return;
        Polygon polygon = Perspective.getCanvasTilePoly(client, local);
        if (polygon != null) {
            g.setColor(color);
            g.fill(polygon);
        }
    }

    private void draw(Graphics2D g, FontMetrics metrics, int x, int y, String text, Color color) {
        int left = x - metrics.stringWidth(text) / 2;
        g.setColor(Color.BLACK);
        g.drawString(text, left + 1, y + 1);
        g.setColor(color);
        g.drawString(text, left, y);
    }
}

package com.celebritymode;

import com.celebritymode.fan.FanManager;
import com.celebritymode.overlay.CelebrityModeOverlay;
import com.google.inject.Provides;

import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.*;

import javax.inject.*;

@PluginDescriptor(
        name = "Celebrity Mode",
        description = "A purely cosmetic entourage of simulated fans",
        tags = {"fun", "cosmetic", "followers", "fans", "celebrity"})
public class CelebrityModePlugin extends Plugin {
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private OverlayManager overlayManager;
    @Inject private FanManager fanManager;
    @Inject private CelebrityModeOverlay overlay;
    private final EnumMap<Skill, Integer> levels = new EnumMap<>(Skill.class);
    private volatile boolean enabled;

    @Provides
    CelebrityModeConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(CelebrityModeConfig.class);
    }

    @Provides
    @Singleton
    Random provideRandom() {
        return new Random();
    }

    @Override
    protected void startUp() {
        enabled = true;
        overlayManager.add(overlay);
        clientThread.invoke(
                () -> {
                    if (enabled) {
                        fanManager.cleanup();
                        levels.clear();
                    }
                });
    }

    @Override
    protected void shutDown() {
        enabled = false;
        overlayManager.remove(overlay);
        clientThread.invoke(
                () -> {
                    if (!enabled) {
                        fanManager.cleanup();
                        levels.clear();
                    }
                });
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (enabled) fanManager.onGameTick(client.getLocalPlayer());
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (enabled) fanManager.onClientTick();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        fanManager.onGameStateChanged(event.getGameState());
        if (event.getGameState() != GameState.LOGGED_IN
                && event.getGameState() != GameState.LOADING) levels.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (enabled && CelebrityModeConfig.GROUP.equals(event.getGroup()))
            clientThread.invoke(
                    () -> {
                        if (enabled) fanManager.onConfigChanged(event.getKey());
                    });
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        Integer old = levels.put(event.getSkill(), event.getLevel());
        if (enabled && client.getGameState() == GameState.LOGGED_IN) {
            fanManager.onExperience(event.getSkill(), event.getXp());
            if (old != null && event.getLevel() > old)
                fanManager.reactLevel(event.getSkill(), event.getLevel());
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (enabled && client.getGameState() == GameState.LOGGED_IN)
            fanManager.onMenuOption(event.getMenuOption());
    }

    @Subscribe
    public void onActorDeath(ActorDeath event) {
        if (enabled && event.getActor() == client.getLocalPlayer()) fanManager.react(true);
    }
}

